class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        cnt = [[0] * 11 for _ in range(n)]
        for p, c in pick:
            cnt[p][c] += 1
        return sum(any(c > i for c in cnt[i]) for i in range(n))

