class Solution {
public:
    int winningPlayerCount(int n, vector<vector<int>>& pick) {
        vector<array<int, 11>> cnt(n);
        for (auto& a : cnt) a.fill(0);
        for (auto& p : pick) cnt[p[0]][p[1]]++;
        int ans = 0;
        for (int i = 0; i < n; i++)
            for (int c = 0; c < 11; c++)
                if (cnt[i][c] > i) { ans++; break; }
        return ans;
    }
};

