class Solution {
    public int winningPlayerCount(int n, int[][] pick) {
        int[][] cnt = new int[n][11];
        for (int[] p : pick) cnt[p[0]][p[1]]++;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            boolean win = false;
            for (int c = 0; c < 11 && !win; c++) win = cnt[i][c] > i;
            if (win) ans++;
        }
        return ans;
    }
}

