class Solution {
    public int winningPlayerCount(int n, int[][] pick) {
        List<Map<Integer, Integer>> m = new ArrayList<>();
        for (int i = 0; i < n; i++) m.add(new HashMap<>());
        for (int[] p : pick) m.get(p[0]).merge(p[1], 1, Integer::sum);
        int ans = 0;
        for (int i = 0; i < n; i++) {
            boolean win = false;
            for (int v : m.get(i).values()) if (v > i) { win = true; break; }
            if (win) ans++;
        }
        return ans;
    }
}

